import{_ as i,o as n,c as t,ag as a}from"./chunks/framework.4yUrvjMt.js";const p=JSON.parse('{"title":"ADR-004: Plugin System Design","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/decisions/ADR-004-plugin-system.md","filePath":"architecture/decisions/ADR-004-plugin-system.md"}'),o={name:"architecture/decisions/ADR-004-plugin-system.md"};function s(l,e,r,c,d,u){return n(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-004-plugin-system-design" tabindex="-1">ADR-004: Plugin System Design <a class="header-anchor" href="#adr-004-plugin-system-design" aria-label="Permalink to &quot;ADR-004: Plugin System Design&quot;">​</a></h1><p><strong>Status:</strong> Accepted<br><strong>Date:</strong> 2024-01-01</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Cross-cutting concerns like cost tracking, telemetry, alerting, and audit logging should not pollute pipeline business logic. We need a clean extension mechanism.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Pravaha provides a <code>PravahaPlugin</code> interface with optional lifecycle hooks:</p><ul><li><code>onPipelineStart</code> — called when a run begins</li><li><code>onStepComplete</code> — called after every step (success or failure)</li><li><code>onPipelineComplete</code> — called when a run finishes</li><li><code>onError</code> — called on any pipeline error</li></ul><p>The <code>PluginRegistry</code> collects plugins and safely invokes hooks. Plugin errors are caught and logged — they never crash the pipeline. This is a hard guarantee.</p><p>Plugins are registered at pipeline construction time and cannot be added to a running pipeline.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Positive:</strong></p><ul><li>Cost tracking, observability, alerting — all zero-touch additions</li><li>Pipeline logic is unmodified by cross-cutting concerns</li><li>Plugin failure isolation prevents cascading failures</li><li>Plugins are testable in isolation</li></ul><p><strong>Negative:</strong></p><ul><li>Plugins cannot alter pipeline execution flow (by design)</li><li>Async plugins slow each step by the hook duration</li><li>Plugin errors are silent (logged only) — requires monitoring</li></ul>',14)])])}const h=i(o,[["render",s]]);export{p as __pageData,h as default};
